const input=$json.body??$json;
const msg=String(input.seller_response||input.message||input.inbound_message||"").trim();
const text=msg.toLowerCase();
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao);
const nums=(msg.match(/\\$?\\d[\\d,]*(?:\\.\\d+)?/g)||[]).map(v=>Number(v.replace(/[$,]/g,""))).filter(Number.isFinite);
const counter=Number(input.counteroffer_amount??nums[0]);
const validMao=Number.isFinite(mao)&&mao>0;
const validCounter=Number.isFinite(counter)&&counter>0;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dnc=Boolean(input.dnc||input.do_not_contact);
let classification="other_response",decision="needs_review",nextWorkflow="WF-126",human=true,reason="seller response requires final negotiation review";
if(dnc||/\\b(stop|remove me|do not contact|don't contact)\\b/i.test(text)){classification="dnc";decision="blocked";reason="seller requested no further contact";}
else if(blockers.length){decision="blocked";reason="active blockers present";}
else if(!msg){classification="no_response";decision="timeout_followup";nextWorkflow="WF-290";human=false;reason="no seller response supplied";}
else if(/\\b(no|not interested|pass|decline|rejected)\\b/i.test(text)){classification="rejected";decision="reengage";nextWorkflow="WF-261";reason="seller rejected the current terms";}
else if(/\\b(yes|accept|accepted|deal|agreed|let's do it)\\b/i.test(text)){classification="accepted";decision="contract_ready";nextWorkflow="WF-201";reason="seller accepted the proposed terms";}
else if(validCounter&&/(\\$|offer|price|counter|would you do|can you do|i need)/i.test(text)){
  classification="counteroffer";
  if(counter<=mao){decision="counteroffer_within_mao";nextWorkflow="WF-201";reason="counteroffer is within protected dynamic MAO";}
  else if(validMao&&counter<=mao*1.10){decision="counteroffer_near_mao";nextWorkflow="WF-298";reason="counteroffer is above MAO but within controlled negotiation band";}
  else{decision="counteroffer_above_mao";nextWorkflow="WF-261";reason="counteroffer exceeds protected dynamic MAO";}
}
else if(/\\b(what|how|when|where|why|explain|question)\\b/i.test(text)){classification="question";decision="clarification";nextWorkflow="WF-298";reason="seller needs clarification before final negotiation decision";}
const guardrail=(validCounter&&validMao&&counter>mao)?"HARD_BLOCK_ABOVE_DYNAMIC_MAO":"PASS";
const idempotencyKey=input.idempotency_key||`wf-300:${input.deal_id||input.dispatch_id||"unknown"}:${input.provider_event_id||input.version||1}`;
return [{json:{...input,workflow:"WF-300",workflow_name:"Seller Response → Final Negotiation Decision & Contract/Re-engagement Controller",status:decision==="blocked"?"blocked":decision==="contract_ready"?"contract_ready":decision==="counteroffer_within_mao"?"contract_ready":decision==="counteroffer_near_mao"?"revised_offer_ready":decision==="counteroffer_above_mao"?"above_mao_reengagement":"negotiation_review",final_negotiation:{classification,decision,counteroffer_amount:validCounter?counter:null,dynamic_mao:validMao?mao:null,guardrail,reason},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"final_negotiation_decision",idempotency_key:idempotencyKey}}}];
